export function MetatileBehavior_IsPlayerFacingWirelessBoxResults(tile: number, playerDir: number): boolean
{
    if (playerDir != CONNECTION_NORTH) 
        return false;
    else if (tile == MB_WIRELESS_BOX_RESULTS) 
        return true;
    else
        return false;
}

